use eyre::Result;

mod ls;
mod sync;

/// Agent skills the active tools ship, from their packslips
///
/// A tool installed with the `packslip:` backend may declare an agent skill: a
/// directory holding `SKILL.md` and whatever it references, in the Agent Skills
/// format. mise knows which version of each tool is active here, so it can hand
/// an agent the skill for exactly that version.
#[derive(Debug, usage_rs::Args)]
#[usage(alias = "skill", verbatim_doc_comment)]
pub(crate) struct Skills {
    #[usage(subcommand)]
    command: Option<Commands>,
}

#[derive(Debug, usage_rs::Subcommands)]
enum Commands {
    Ls(ls::SkillsLs),
    Sync(sync::SkillsSync),
}

impl Commands {
    async fn run(self) -> Result<()> {
        match self {
            Self::Ls(cmd) => cmd.run().await,
            Self::Sync(cmd) => cmd.run().await,
        }
    }
}

impl Skills {
    pub(crate) async fn run(self) -> Result<()> {
        self.command
            .unwrap_or(Commands::Ls(ls::SkillsLs::default()))
            .run()
            .await
    }
}
use eyre::Result;
use tabled::{Table, Tabled};

use crate::config::Config;
use crate::ui::table;

/// List the skills the active tools declare
///
/// Each line is a skill of a tool that is installed and active in the current
/// directory, with the version it belongs to and the directory holding its
/// `SKILL.md`.
#[derive(Debug, Default, usage_rs::Args)]
#[usage(visible_alias = "list", verbatim_doc_comment, after_long_help = AFTER_LONG_HELP)]
pub(super) struct SkillsLs {
    /// Output in JSON format
    #[usage(long, short = 'J')]
    json: bool,
}

#[derive(Tabled)]
struct Row {
    #[tabled(rename = "Skill")]
    name: String,
    #[tabled(rename = "Tool")]
    tool: String,
    #[tabled(rename = "Version")]
    version: String,
    #[tabled(rename = "Path")]
    path: String,
}

impl SkillsLs {
    pub(super) async fn run(self) -> Result<()> {
        let config = Config::get().await?;
        let skills = crate::packslip::active_skills(&config).await?;
        if self.json {
            miseprintln!("{}", serde_json::to_string_pretty(&skills)?);
            return Ok(());
        }
        if skills.is_empty() {
            miseprintln!("no skills declared by the active tools");
            return Ok(());
        }
        let rows = skills.into_iter().map(|s| Row {
            name: s.name,
            tool: s.tool,
            version: s.version,
            path: s.path.display().to_string(),
        });
        let mut table = Table::new(rows);
        table::print(&mut table, false)
    }
}

static AFTER_LONG_HELP: &str = color_print::cstr!(
    r#"<bold><underline>Examples:</underline></bold>

    $ <bold>mise skills ls</bold>
    Skill  Tool                        Version  Path
    mise   packslip:github.com/jdx/mise  2026.9.1  ~/.local/share/mise/installs/.../skills/mise
"#
);
use std::path::PathBuf;

use eyre::Result;

use crate::config::{Config, Settings};
use crate::dirs;

/// Link the active tools' skills where an agent looks for them
///
/// Writes one symlink per skill into DIR, named after the skill and pointing
/// at the directory of the version that is active here. DIR defaults to the
/// `skills.dir` setting, `.claude/skills`, under the project root: the
/// directory of the nearest mise config. Run it again after `mise use` changes
/// a version and the links follow, or set `skills.auto_sync` to have mise do
/// that after every install and `mise use`.
///
/// Only links mise made, which point into its installs directory, are ever
/// replaced or, with --prune or the `skills.prune` setting, removed. A real
/// directory or a link of your own at a skill's name is left alone and reported.
#[derive(Debug, usage_rs::Args)]
#[usage(verbatim_doc_comment, after_long_help = AFTER_LONG_HELP, effect = "write")]
pub(super) struct SkillsSync {
    /// The directory to link skills into
    #[usage(long, value_hint = usage_rs::ValueHint::DirPath)]
    dir: Option<PathBuf>,

    /// Link into ~/.claude/skills instead of the project's directory
    #[usage(long, short, conflicts = "dir")]
    global: bool,

    /// Remove links mise made for skills that are no longer active
    #[usage(long)]
    prune: bool,
}

impl SkillsSync {
    pub(super) async fn run(self) -> Result<()> {
        let config = Config::get().await?;
        let skills = crate::packslip::active_skills(&config).await?;
        let settings = Settings::get();
        let dir = match (&self.dir, self.global) {
            (Some(dir), _) => dir.clone(),
            (None, true) => crate::packslip::skills_dir(&dirs::HOME),
            (None, false) => crate::packslip::skills_dir(
                &config
                    .project_root
                    .clone()
                    .map(Ok)
                    .unwrap_or_else(std::env::current_dir)?,
            ),
        };
        let prune = self.prune || settings.skills.prune;
        if skills.is_empty() && !prune {
            miseprintln!("no skills declared by the active tools; nothing to link");
            return Ok(());
        }
        let report = crate::packslip::sync_skills(&dir, &skills, &dirs::INSTALLS, prune)?;
        for name in &report.linked {
            let skill = skills.iter().find(|s| &s.name == name);
            miseprintln!(
                "linked {} -> {}",
                dir.join(name).display(),
                skill
                    .map(|s| s.path.display().to_string())
                    .unwrap_or_default()
            );
        }
        for name in &report.pruned {
            miseprintln!("removed {}", dir.join(name).display());
        }
        for (name, why) in &report.skipped {
            warn!("skipped {name}: {why}");
        }
        if report.linked.is_empty() && report.pruned.is_empty() {
            miseprintln!(
                "{} skill(s) already linked in {}",
                report.unchanged.len(),
                dir.display()
            );
        }
        Ok(())
    }
}

static AFTER_LONG_HELP: &str = color_print::cstr!(
    r#"<bold><underline>Examples:</underline></bold>

    # into the project's .claude/skills, or wherever skills.dir says
    $ <bold>mise skills sync</bold>

    # somewhere else, and drop links for skills that are no longer active
    $ <bold>mise skills sync --dir .agents/skills --prune</bold>
"#
);
use eyre::Result;

mod forget;
mod pins;

/// The signers mise accepts packslips from
///
/// A tool installed with the `packslip:` backend is verified against the
/// identity its project name implies, and mise then remembers which signer
/// it accepted, the way SSH remembers hosts. A later release from another
/// signer, a weaker scheme, a repackager where the vendor signed before, or
/// one that drops build provenance is refused until a person says so.
#[derive(Debug, usage_rs::Args)]
#[usage(verbatim_doc_comment)]
pub(crate) struct Packslip {
    #[usage(subcommand)]
    command: Option<Commands>,
}

#[derive(Debug, usage_rs::Subcommands)]
enum Commands {
    Forget(forget::PackslipForget),
    Pins(pins::PackslipPins),
}

impl Commands {
    fn run(self) -> Result<()> {
        match self {
            Self::Forget(cmd) => cmd.run(),
            Self::Pins(cmd) => cmd.run(),
        }
    }
}

impl Packslip {
    pub(crate) async fn run(self) -> Result<()> {
        self.command
            .unwrap_or(Commands::Pins(pins::PackslipPins::default()))
            .run()
    }
}
use eyre::Result;
use tabled::{Table, Tabled};

use crate::packslip_pins;
use crate::ui::table;

/// List the signers mise has accepted packslips from
#[derive(Debug, Default, usage_rs::Args)]
#[usage(visible_alias = "list", verbatim_doc_comment)]
pub(super) struct PackslipPins {
    /// Output in JSON format
    #[usage(long, short = 'J')]
    json: bool,
}

#[derive(Tabled)]
struct Row {
    #[tabled(rename = "Project")]
    project: String,
    #[tabled(rename = "Scheme")]
    scheme: String,
    #[tabled(rename = "Signer")]
    signer: String,
    #[tabled(rename = "Attested by")]
    attested_by: String,
    #[tabled(rename = "Provenance")]
    provenance: String,
}

impl PackslipPins {
    pub(super) fn run(self) -> Result<()> {
        let pins = packslip_pins::list()?;
        if self.json {
            miseprintln!("{}", serde_json::to_string_pretty(&pins)?);
            return Ok(());
        }
        if pins.is_empty() {
            miseprintln!("no packslip signers pinned yet");
            return Ok(());
        }
        let rows = pins.into_iter().map(|(project, pin)| Row {
            project,
            scheme: pin.scheme,
            signer: pin.signer,
            attested_by: pin.attested_by,
            provenance: if pin.provenance { "yes" } else { "no" }.to_string(),
        });
        let mut table = Table::new(rows);
        table::print(&mut table, false)
    }
}
use eyre::Result;

use crate::backend::packslip::project_name;
use crate::packslip_pins;

/// Forget a project's pinned signer, so the next release accepted sets it again
///
/// Do this when the vendor has announced a new signing identity or key. The
/// project is named as the packslip backend names it: `github.com/owner/repo`,
/// `owner/repo`, or a host such as `tool.example.com`, with or without the
/// `packslip:` prefix.
#[derive(Debug, usage_rs::Args)]
#[usage(verbatim_doc_comment, effect = "write")]
pub(super) struct PackslipForget {
    /// The project whose pin to drop
    project: String,
}

impl PackslipForget {
    pub(super) fn run(self) -> Result<()> {
        let name = self
            .project
            .strip_prefix("packslip:")
            .unwrap_or(&self.project);
        let project = project_name(name)?;
        if packslip_pins::forget(&project)? {
            miseprintln!("forgot the pinned signer of packslip:{project}");
        } else {
            miseprintln!("packslip:{project} had no pinned signer");
        }
        Ok(())
    }
}
