#[derive(Tabled)]
struct Row {
    #[tabled(rename = "Project")]
    project: String,
    #[tabled(rename = "Scheme")]
    scheme: String,
    #[tabled(rename = "Signer")]
    signer: String,
    #[tabled(rename = "Attested by")]
